problem:
Problem description
- There is a candidate set $$\mathcal{C}$$ indexed by $$i \in \mathcal{C}$$.
- The recruitment decision is made over one planning horizon $$\mathcal{T}$$.
- Each candidate $$i$$ has a hiring cost $$k_i$$, a work-experience value $$e_i$$, and a qualification label $$q_i \in \mathcal{Q}$$.
- A binary attribute $$a_i \in \{0,1\}$$ indicates whether candidate $$i$$ has an advanced degree level, meaning master’s degree or doctoral degree.
- The company wants to choose a subset of candidates that minimizes the total hiring cost.
- The hiring plan must satisfy the following business rules:
  - each candidate is either hired or not hired;
  - the total number of hired candidates must stay between the minimum hiring requirement $$L$$ and the maximum hiring limit $$U$$;
  - the total hiring cost must not exceed the available budget $$B$$;
  - at least one selected candidate must have an advanced degree level;
  - the total work experience of all selected candidates must be at least the required experience threshold $$E^{\min}$$;
  - for each incompatible pair of candidates in the conflict set $$\mathcal{I}$$, at most one of the two may be selected.
- A solution is represented by:
  - binary selection variables $$x_i$$ for all $$i \in \mathcal{C}$$, where $$x_i=1$$ means candidate $$i$$ is hired and $$x_i=0$$ means candidate $$i$$ is not hired;
  - the selected candidate subset $$\mathcal{S} \subseteq \mathcal{C}$$ induced by the binary selection variables.

Input Format
{
  "planning_horizon": {
    "name": "$$\mathcal{T}$$",
    "description": "Recruitment planning horizon"
  },
  "candidates": {
    "name": "$$\mathcal{C}$$",
    "type": "array",
    "shape": "$$n$$ entries, where $$n = |\mathcal{C}|$$",
    "fields": {
      "id": "Candidate identifier",
      "hiring_cost": "$$k_i$$, hiring cost of candidate $$i$$",
      "experience": "$$e_i$$, work experience of candidate $$i$$",
      "qualification": "$$q_i \\in \\mathcal{Q}$$, qualification label of candidate $$i$$",
      "advanced_degree_flag": "$$a_i \\in \\{0,1\\}$$, equals $$1$$ if candidate $$i$$ has a master’s degree or doctoral degree"
    }
  },
  "budget": "$$B$$, maximum total hiring cost",
  "minimum_hires": "$$L$$, minimum number of hires",
  "maximum_hires": "$$U$$, maximum number of hires",
  "minimum_advanced_degree_hires": "$$G$$, minimum number of selected candidates with $$a_i = 1$$",
  "minimum_total_experience": "$$E^{\min}$$, minimum total experience required from selected candidates",
  "incompatible_pairs": {
    "name": "$$\mathcal{I}$$",
    "type": "array",
    "shape": "list of unordered index pairs $$\\{i,j\\}$$ with $$i,j \\in \\mathcal{C}$$",
    "description": "Pairs of candidates that cannot both be selected"
  }
}

Output Format
{
  "selection": {
    "name": "$$x$$",
    "type": "array",
    "shape": "$$n$$ binary entries, where $$n = |\mathcal{C}|$$",
    "description": "Binary hiring decision for each candidate $$i \\in \\mathcal{C}$$; $$x_i = 1$$ if candidate $$i$$ is selected and $$x_i = 0$$ otherwise"
  },
  "selected_candidates": {
    "name": "$$\\mathcal{S}$$",
    "type": "array",
    "shape": "subset of $$\\mathcal{C}$$",
    "description": "Indices or identifiers of the selected candidates"
  }
}

