      "advanced_degree_flag": 1
    },
    {
      "id": "C",
      "hiring_cost": 21000,
      "experience": 4,
      "qualification": "Doctoral degree",
      "advanced_degree_flag": 1
    },
    {
      "id": "D",
      "hiring_cost": 3000,
